function gradDesc(a, b, c, x0, lr, iters){
  var x=x0;
  for(var i=0;i<iters;i++){ var g=2*a*x + b; x = x - lr*g; }
  return x;
}
var EXPORTS={gradDesc:gradDesc};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.GradientDescentForgePure = EXPORTS; }
